    private static void CadaEstadoTieneSuIcono()
    {
        var t = Capacidad("U.WindowsClient.Ui.IconosDelNotch");
        var de = t?.GetMethod("De");
        var estados = Capacidad("U.WindowsClient.Ui.EstadoDelNotch");
        Debe(t != null && de != null && estados != null,
            "todavía no existe «Ui.IconosDelNotch» (spec 028, promesa 253). "
            + "La promesa está escrita y en rojo, que es donde tiene que estar");
        if (t == null || de == null || estados == null) return;

        var dibujos = new List<string>();
        foreach (string nombre in Enum.GetNames(estados))
        {
            string trazo = (string)de.Invoke(null, new[] { Enum.Parse(estados, nombre) })!;
            Debe(trazo.Length > 0, $"«{nombre}» tiene icono: un estado sin dibujo deja un hueco en la pieza");
            Debe(trazo.TrimStart().StartsWith("M", StringComparison.OrdinalIgnoreCase),
                $"«{nombre}» es un trazo de vector y no una letra ni un emoji ({trazo[..Math.Min(12, trazo.Length)]}…): "
                + "un emoji trae su propio color y su propia métrica, y se lee como un adorno pegado encima");
            dibujos.Add(trazo);
        }
        Debe(dibujos.Distinct().Count() == dibujos.Count,
            "no hay dos estados con el mismo dibujo: un icono que se repite es un estado que no se distingue");

        double caja = (double)t.GetField("Caja", BindingFlags.Public | BindingFlags.Static)!.GetRawConstantValue()!;
        double grosor = (double)t.GetField("Grosor", BindingFlags.Public | BindingFlags.Static)!.GetRawConstantValue()!;
        Debe(caja == 24, $"todos se dibujan en la misma caja de 24 ({caja}): es lo que hace que pesen igual");
        Debe(grosor >= 1.2 && grosor <= 2.0, $"y con un solo grosor de trazo monolínea ({grosor})");
    }

    private static void MirarNoDejaRastroEnOpenAI()
    {
        var t = Capacidad("U.WindowsClient.Voice.MiradaSubida");
        Debe(t != null, "todavía no existe «Voice.MiradaSubida» (spec 027, promesa 250). "
            + "La promesa está escrita y en rojo, que es donde tiene que estar");
        if (t == null) return;

        var subidas = new List<int>();
        var borradas = new List<string>();
        Func<byte[], Task<string>> subir = b => { subidas.Add(b.Length); return Task.FromResult($"file-{subidas.Count}"); };
        Func<string, Task> borrar = id => { borradas.Add(id); return Task.CompletedTask; };
        var mirada = Activator.CreateInstance(t, subir, borrar)!;
        var mSubir = t.GetMethod("SubirAsync")!;
        var mSoltar = t.GetMethod("SoltarAsync")!;
        string Sube(byte[] b) => ((Task<string>)mSubir.Invoke(mirada, new object[] { b })!).GetAwaiter().GetResult();
        void Suelta() => ((Task)mSoltar.Invoke(mirada, null)!).GetAwaiter().GetResult();

        Suelta();
        Debe(borradas.Count == 0, "sin nada subido no se borra nada: no se inventa una llamada");

        string id = Sube(new byte[] { 1, 2, 3, 4 });
        Debe(id == "file-1" && subidas.Count == 1, $"subir devuelve el identificador con el que se mira ({id})");
        Debe(borradas.Count == 0, "y mientras se mira, la copia sigue ahí: borrarla antes sería mirar a nada");

        // MIRAR DOS VECES NO PUEDE BORRAR LA PRIMERA. La referencia de la primera SIGUE en el historial de la
        // sesión, así que el modelo la relee en cada respuesta posterior: borrarla deja esa conversación
        // apuntando a un archivo que no existe, y el servidor contesta «Files [...] were not found» sin parar.
        string id2 = Sube(new byte[] { 9 });
        Debe(id2 == "file-2", "una mirada nueva sube su propia copia");
        Debe(borradas.Count == 0,
            $"y la anterior SIGUE en pie: subir la segunda no borra la primera (borradas: {borradas.Count})");

        Suelta();
        Debe(borradas.SequenceEqual(new[] { "file-1", "file-2" }),
            $"al cerrar se retiran TODAS las que subió esta conversación, y ninguna antes (borradas: {string.Join(", ", borradas)})");
        Suelta();
        Debe(borradas.Count == 2, "soltar dos veces no borra dos veces: la segunda no tiene nada que borrar");

        // Y SI LA MIRADA FALLA, la copia se borra igual: un fallo no puede dejar basura en la cuenta.
        string id3 = Sube(new byte[] { 7 });
        Debe(id3 == "file-3", "después de cerrar, una mirada nueva empieza su propia cuenta");
        Suelta();
        Debe(borradas.SequenceEqual(new[] { "file-1", "file-2", "file-3" }),
            "el borrado no depende de que la mirada saliera bien: se suelta pase lo que pase");
    }


    private static void MandarLaFotoNoLaBorraAntesDeVerse()
    {
        var g = GptLiveConReloj(() => 0, "254");
        if (g == null) return;
        var (conv, _, _, tc) = g.Value;
        using (conv)
        {
            var fPuerta   = tc.GetField("_puerta", BindingFlags.NonPublic | BindingFlags.Instance);
            var fAbierta  = tc.GetField("_puertaAbierta", BindingFlags.NonPublic | BindingFlags.Instance);
            var fSube     = tc.GetField("_subeLaMirada", BindingFlags.NonPublic | BindingFlags.Instance);
            var fBorra    = tc.GetField("_borraLaMirada", BindingFlags.NonPublic | BindingFlags.Instance);
            var mFoto     = tc.GetMethod("MandarFotoAsync", BindingFlags.NonPublic | BindingFlags.Instance);
            var mTerminar = tc.GetMethod("TerminarAsync");
            if (fPuerta == null || fAbierta == null || fSube == null || fBorra == null || mFoto == null || mTerminar == null)
            { Pendiente("ConversacionEnVivo._subeLaMirada/_borraLaMirada (por dónde sube la mirada)", "254", "027"); return; }

            var mandados = new List<string>();
            var borradas = new List<string>();
            int subidas = 0;
            fPuerta.SetValue(conv, (Func<string, CancellationToken, Task>)((j, _) => { lock (mandados) mandados.Add(j); return Task.CompletedTask; }));
            fAbierta.SetValue(conv, (Func<bool>)(() => true));
            fSube.SetValue(conv, (Func<byte[], Task<string>>)(_ => Task.FromResult($"file-{Interlocked.Increment(ref subidas)}")));
            fBorra.SetValue(conv, (Func<string, Task>)(id => { lock (borradas) borradas.Add(id); return Task.CompletedTask; }));

            var reloj = System.Diagnostics.Stopwatch.StartNew();
            ((Task)mFoto.Invoke(conv, new object[] { new byte[] { 1, 2, 3, 4 }, CancellationToken.None })!).GetAwaiter().GetResult();
            reloj.Stop();

            // NO SE DUERME. La espera fija de ocho segundos retrasaba el turno del modelo por el mismo tiempo que
            // tardaba en matar la foto: el peor de los dos mundos, lento Y ciego.
            Debe(reloj.ElapsedMilliseconds < 1500,
                $"mandar la foto devuelve el turno enseguida y no duerme esperando al servidor ({reloj.ElapsedMilliseconds} ms)");
            Debe(mandados.Count == 1 && mandados[0].Contains("file-1", StringComparison.Ordinal),
                $"se mandó la referencia de la foto ({mandados.Count} mensaje(s))");
            Debe(borradas.Count == 0,
                $"y al ceder el turno la copia SIGUE en OpenAI: si se borra aquí, el modelo lee un archivo que ya no existe (borradas: {string.Join(", ", borradas)})");

            ((Task)mTerminar.Invoke(conv, null)!).GetAwaiter().GetResult();
            Debe(borradas.SequenceEqual(new[] { "file-1" }),
                $"y al cerrar la conversación sí se retira, que es cuando ya nadie puede leerla (borradas: {string.Join(", ", borradas)})");
        }
    }

    private static void MirarVaAResolucionDePantalla()
    {
        var t = Capacidad("U.WindowsClient.Voice.CapturaDePantalla");
        var m = t?.GetMethod("Medida", BindingFlags.Public | BindingFlags.Static);
        if (m == null) { Pendiente("CapturaDePantalla.Medida (el presupuesto de la foto que viaja)", "256", "027"); return; }

        (int W, int H) Mide(int w, int h)
        {
            var r = m.Invoke(null, new object[] { w, h })!;
            var tt = r.GetType();
            return ((int)tt.GetField("Item1")!.GetValue(r)!, (int)tt.GetField("Item2")!.GetValue(r)!);
        }
        static int Parches(int w, int h) => (int)(Math.Ceiling(w / 32.0) * Math.Ceiling(h / 32.0));
        const int Presupuesto = 2500;

        // LA PANTALLA ENTERA, que es el punto: reducirla era compensar un buzón que ya no existe.
        var (w1, h1) = Mide(1920, 1080);
        Debe(w1 == 1920 && h1 == 1080,
            $"una pantalla de 1080p se manda ENTERA, sin reducir ({w1}x{h1}); cabe en el presupuesto "
            + $"({Parches(1920, 1080)} de {Presupuesto} parches, ~{Math.Ceiling(Parches(1920, 1080) * 1.2)} tokens)");

        // UNA 4K NO CABE, y entonces sí se reduce — hasta caber, no por gusto, y sin deformarse.
        var (w2, h2) = Mide(3840, 2160);
        Debe(Parches(w2, h2) <= Presupuesto,
            $"una 4K se reduce hasta caber en el presupuesto: {w2}x{h2} son {Parches(w2, h2)} parches");
        Debe(w2 < 3840 && Math.Abs((double)w2 / h2 - 3840.0 / 2160.0) < 0.01,
            $"y se reduce conservando la proporción ({w2}x{h2}), que es lo que la deja legible");

        // VERTICAL TAMBIÉN: un monitor girado es el caso que se olvida.
        var (w3, h3) = Mide(1080, 1920);
        Debe(Parches(w3, h3) <= Presupuesto, $"una pantalla vertical tampoco se cuela: {w3}x{h3} son {Parches(w3, h3)} parches");

        // Y NUNCA SE AGRANDA: inventar píxeles no añade nada que ver y sí lo que cobrar.
        var (w4, h4) = Mide(640, 360);
        Debe(w4 == 640 && h4 == 360, $"una pantalla más pequeña que el presupuesto se manda tal cual ({w4}x{h4})");
    }

    private static string Corto120(string t) => t.Length <= 120 ? t : t[..120];


    private static void LlegarEsLlegar()
    {
        // LA REGLA, con los casos reales de los logs del 15 al 17 de septiembre.
        bool Basta(string pedido, string donde) => Mapeador.ComoMePongoDelante.EstarEnElSitioBasta(pedido, donde);
        Debe(Basta("web://www.google.com", "web://google.com"), "«www.» no es otro sitio");
        Debe(Basta("web://google.com", "web://www.google.com"), "ni al revés");
        Debe(Basta("web://docs.google.com/document/u/0/", "web://docs.google.com/document/u/0"), "la barra final no cambia la página pedida");
        Debe(Basta("web://google.com/search?q=DeepSeek", "web://google.com/search"), "la query que el localizador descarta no impide reconocer la página");
        Debe(Basta("web://ycombinator.com", "web://apply.ycombinator.com/apps/4ebb"), "un subdominio del mismo sitio es el mismo sitio, cuando se pidió el sitio");
        Debe(Basta("web://artificialanalysis.ai/models/releases", "web://artificialanalysis.ai/models/releases/gpt-5-6-sol"), "la ruta pedida como comienzo de la real es haber llegado");
        Debe(Basta("web://instagram.com", "web://instagram.com/direct/t/1100"), "y pedir el sitio se cumple con cualquiera de sus páginas, como ya prometia la 24 del mapeador");
        // LO QUE SIGUE SIN BASTAR, y es lo que la 24 del mapeador defiende: pedir una PÁGINA no se cumple con el sitio.
        Debe(!Basta("web://github.com/notifications", "web://github.com"), "pedir una página y estar en la portada NO es haber llegado");
        Debe(!Basta("web://google.com/search", "web://google.com/maps"), "ni estar en otra página del mismo sitio");
        Debe(!Basta("web://github.com", "web://gitlab.com/algo"), "otro sitio no cuenta aunque se parezca");
        Debe(!Basta("web://ycombinator.com", "web://notycombinator.com"), "y «termina igual» no es «es subdominio»: hace falta el punto");

        // Y EL CAMINO TERMINA AL LLEGAR: PasoDelNucleo con un donde que cae en la variante normalizada. Antes agotaba
        // el presupuesto de la web entero (8 s de reloj, 15 s con vueltas) para decir «no hay camino» estando allí.
        var tp = Capacidad("U.WindowsClient.Navigation.PasoDelNucleo");
        var pWeb = tp?.GetProperty("EsperaWebMs");
        if (tp == null || pWeb == null) { Pendiente("PasoDelNucleo.EsperaWebMs", "261", "029"); return; }
        var g = new Nucleo.Grafo();
        g.Observar("web://docs.google.com/spreadsheets/d/1", new[] { new Nucleo.Elemento("uia:name=x", "x", "Button") });
        string donde = "web://docs.google.com/spreadsheets/d/1";
        var paso = Activator.CreateInstance(tp, g,
            (Func<string>)(() => donde),
            (Func<string, string, bool>)((_, _) => true),
            (Func<string, bool>)(dest => { donde = "web://docs.google.com/document/u/0"; return true; }))!;   // el navegador quita la barra
        pWeb.SetValue(paso, 8000);
        var hacia = tp.GetMethod("Hacia")!;
        var cronometro = System.Diagnostics.Stopwatch.StartNew();
        var r = hacia.Invoke(paso, new object[] { "web://docs.google.com/document/u/0/" })!;
        cronometro.Stop();
        bool llegado = (bool)r.GetType().GetProperty("Llegado")!.GetValue(r)!;
        string porque = (string)r.GetType().GetProperty("Porque")!.GetValue(r)!;
        Debe(llegado, $"con el navegador normalizando la ruta, ir a la página es LLEGAR (dijo: «{porque}»)");
        Debe(cronometro.ElapsedMilliseconds < 1500,
            $"y termina al llegar, no al agotar los 8 s del plazo ({cronometro.ElapsedMilliseconds} ms)");
    }

    private static void AbrirNoEsperaALoQueNoLanzo()
    {
        var t = typeof(AbrirSegunElNucleo);
        var pLanzo = t.GetProperty("Lanzo");
        var mEspera = t.GetMethod("EsperarVentanaNueva", BindingFlags.Public | BindingFlags.Static);
        if (pLanzo == null || mEspera == null) { Pendiente("AbrirSegunElNucleo.Lanzo / EsperarVentanaNueva", "262", "029"); return; }

        // TRAER AL FRENTE NO ES LANZAR. Chrome ya estaba abierto: se trae y se contesta; Lanzo queda en falso.
        var ventanas = new List<(IntPtr Hwnd, string Proceso, string Titulo)> { ((IntPtr)7, "chrome.exe", "Google - Google Chrome") };
        var abrir = new AbrirSegunElNucleo(() => "web://google.com", _ => true, _ => "", () => Array.Empty<AbrirSegunElNucleo.AppDelSistema>(),
            _ => throw new InvalidOperationException("no había que lanzar nada"), () => ventanas, _ => true);
        string r = abrir.Abrir("chrome", "existente");
        Debe(r.Contains("ya estaba abierta", StringComparison.Ordinal), $"una app abierta se trae, no se lanza (dijo: «{r}»)");
        Debe(!(bool)pLanzo.GetValue(abrir)!, "y queda dicho que NO se lanzó nada: no hay ventana nueva que esperar");

        // LANZAR SÍ LANZA, y lo dice.
        var lanzadas = new List<string>();
        var abrir2 = new AbrirSegunElNucleo(() => "uia://explorer.exe/x", _ => false, _ => "",
            () => new[] { new AbrirSegunElNucleo.AppDelSistema("Paint", "mspaint") },
            id => { lanzadas.Add(id); return true; });
        abrir2.Abrir("paint");
        Debe(lanzadas.Count == 1 && (bool)pLanzo.GetValue(abrir2)!, "cuando se lanza de verdad, Lanzo lo dice: ahí sí hay una ventana que esperar");

        // Y LA ESPERA A LA VENTANA NUEVA VA CON RELOJ: un enumerador de 400 ms y un tope de 1200 no puede tardar
        // cuarenta vueltas. Es la misma prueba que la 245, sobre el sexto bucle.
        const int LENTO = 400, TOPE = 1200;
        var previas = new HashSet<IntPtr> { (IntPtr)7 };
        Func<IReadOnlyList<(IntPtr Hwnd, string Proceso, string Titulo)>> lento = () => { Thread.Sleep(LENTO); return ventanas; };
        var crono = System.Diagnostics.Stopwatch.StartNew();
        var nueva = mEspera.Invoke(null, new object[] { "chrome", previas, lento, TOPE })!;
        long tardo = crono.ElapsedMilliseconds;
        var hwnd = (IntPtr)nueva.GetType().GetField("Item1")!.GetValue(nueva)!;
        Debe(hwnd == IntPtr.Zero, "sin ventana nueva no se inventa una");
        Debe(tardo < TOPE + 3 * LENTO, $"y esperar {TOPE} ms con un enumerador de {LENTO} ms no puede tardar {tardo} ms");

        // Y CUANDO APARECE, SE SALE EN EL ACTO.
        int vueltas = 0;
        Func<IReadOnlyList<(IntPtr Hwnd, string Proceso, string Titulo)>> aparece = () =>
        {
            vueltas++;
            return vueltas < 2 ? ventanas : new List<(IntPtr, string, string)>(ventanas) { ((IntPtr)9, "chrome.exe", "Nueva - Google Chrome") };
        };
        crono.Restart();
        var nueva2 = mEspera.Invoke(null, new object[] { "chrome", previas, aparece, 8000 })!;
        var hwnd2 = (IntPtr)nueva2.GetType().GetField("Item1")!.GetValue(nueva2)!;
        Debe(hwnd2 == (IntPtr)9 && crono.ElapsedMilliseconds < 2000, $"al aparecer la ventana se devuelve en el acto ({crono.ElapsedMilliseconds} ms), no al final del plazo");
    }


    private static void UnActoCuentaLoQueDejoDelante()
    {
        var t = Capacidad("U.WindowsClient.Mcp.ComoSeContesta");
        var mLleva = t?.GetMethod("LlevaInventario", BindingFlags.Public | BindingFlags.Static);
        var mPegar = t?.GetMethod("Pegar", BindingFlags.Public | BindingFlags.Static);
        var pSeam = typeof(SurfaceMapTools).GetProperty("InventarioParaLosActos");
        if (t == null || mLleva == null || mPegar == null || pSeam == null)
        { Pendiente("Mcp.ComoSeContesta (LlevaInventario, Pegar) y SurfaceMapTools.InventarioParaLosActos", "263", "029"); return; }
        bool Lleva(string tool, string r) => (bool)mLleva.Invoke(null, new object[] { tool, r })!;
        string Pega(string r, string inv) => (string)mPegar.Invoke(null, new object[] { r, inv })!;

        // LA REGLA, pura.
        Debe(Lleva("map_go_to", "te puse delante de «github.com»"), "ir es un acto: lleva lo que hay delante");
        Debe(Lleva("map_type", "no pude escribir: el campo no está"), "y también cuando no pudo: la 38 ya pedía decir QUÉ hay ahora");
        Debe(Lleva("map_take", "pulsé «x» y ahora estás en «y»") && Lleva("map_open_app", "«chrome» ya estaba abierta") && Lleva("map_scroll", "desplazado") && Lleva("map_unblock", "DESBLOQUEADO"),
            "pulsar, abrir, desplazar y desbloquear son actos");
        Debe(!Lleva("map_where_am_i", "Estás en «x»") && !Lleva("map_what_i_see", "EN PANTALLA AHORA") && !Lleva("map_look", "aquí tienes"),
            "un saber no lo repite: ya es lo que contesta");
        Debe(!Lleva("map_go_to", "falta `surface`: a dónde hay que ir"), "una llamada que ni llegó a actuar no lo añade");
        Debe(!Lleva("map_go_to", "todavía no sé navegar: el núcleo no está conectado."), "ni una sin núcleo");
        string inv = "EN PANTALLA AHORA, en «web://github.com» (2 elemento(s)):\n  «Buscar» (Edit)\n  «Nuevo» (Button)\n";
        Debe(!Lleva("map_take", "pulsé «x».\n\n" + inv), "y si ya lo lleva, no se pega dos veces");
        string pegado = Pega("te puse delante de «github.com»", inv);
        Debe(pegado.StartsWith("te puse delante de «github.com»", StringComparison.Ordinal) && pegado.Contains("\n\nEN PANTALLA AHORA, en «web://github.com»", StringComparison.Ordinal),
            $"lo que pasó va PRIMERO y el inventario detrás, separado («{(pegado.Length > 80 ? pegado[..80] : pegado)}»)");
        Debe(Pega("te puse delante", "no sé en qué pantalla estoy") == "te puse delante", "sin inventario de verdad no se pega ruido");

        // EL DESPACHO, con el núcleo y el inventario falsos: ir y abrir lo pegan, un saber no, y sin argumento no.
        var mapa = new SurfaceMapTools(() => null);
        mapa.PorElNucleo = destino => $"te puse delante de «{destino}»";
        mapa.AbrirPorElNucleo = (app, _) => $"«{app}» está delante.";
        int pedidos = 0;
        pSeam.SetValue(mapa, (Func<string>)(() => { pedidos++; return inv; }));

        string r1 = mapa.Call("map_go_to", new Dictionary<string, string> { ["surface"] = "web://github.com" });
        Debe(r1.StartsWith("te puse delante de «web://github.com»", StringComparison.Ordinal) && r1.Contains("«Nuevo» (Button)", StringComparison.Ordinal),
            $"ir contesta lo que pasó Y lo que hay delante (dijo: «{(r1.Length > 90 ? r1[..90] : r1)}»)");
        string r2 = mapa.Call("map_open_app", new Dictionary<string, string> { ["app"] = "chrome" });
        Debe(r2.Contains("«Nuevo» (Button)", StringComparison.Ordinal), "abrir también");
        string r3 = mapa.Call("map_go_to", new Dictionary<string, string>());
        Debe(!r3.Contains("«Nuevo» (Button)", StringComparison.Ordinal), $"sin argumento no se actuó, y no se pega nada (dijo: «{r3}»)");
        string r4 = mapa.Call("map_where_am_i", new Dictionary<string, string>());
        Debe(!r4.Contains("«Nuevo» (Button)", StringComparison.Ordinal), "y un saber no lo repite");
        Debe(pedidos == 2, $"el inventario se leyó una vez por acto, y sólo por acto ({pedidos})");

        // Y SE LE DICE AL MODELO, que es lo que de verdad quita las vueltas.
        var tc = Cap004("U.WindowsClient.Voice.ConversacionEnVivo");
        var herramientas = tc?.GetMethod("Herramientas", BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static)?.Invoke(null, null) as System.Collections.IEnumerable;
        string desc = "";
        if (herramientas != null)
            foreach (var u in herramientas)
                if ((string?)u?.GetType().GetProperty("Nombre")?.GetValue(u) == "map_what_i_see")
                    desc = (string?)u!.GetType().GetProperty("Descripcion")?.GetValue(u) ?? "";
        Debe(desc.Contains("DESPUÉS DE", StringComparison.Ordinal) && desc.Contains("no hace falta", StringComparison.OrdinalIgnoreCase),
            $"el catálogo de map_what_i_see dice que después de un acto no hace falta pedirla («{(desc.Length > 100 ? desc[..100] : desc)}»)");
        string instrucciones = (string?)tc?.GetField("Instrucciones", BindingFlags.NonPublic | BindingFlags.Static)?.GetRawConstantValue() ?? "";
        Debe(instrucciones.Contains("CADA ACTO TE CUENTA LO QUE DEJÓ DELANTE", StringComparison.Ordinal),
            "y las instrucciones lo dicen con todas las letras");
    }


    private static void LaCompuertaMiraOtraVezAntesDeRendirse()
    {
        var pMira = typeof(RecorrerSegunElNucleo).GetProperty("MiraOtraVez");
        if (pMira == null) { Pendiente("RecorrerSegunElNucleo.MiraOtraVez (la compuerta mira otra vez)", "264", "030"); return; }

        // «Viejo» está RECORDADO en la pantalla pero la última observación del mapa no lo trae: hoy la 56 dice «no lo veo».
        Nucleo.Grafo Mundo()
        {
            var g = MundoDeTres();
            g.Observar("uia://x.exe/a", new[] { new Nucleo.Elemento("s:1", "Uno", "Button"), new Nucleo.Elemento("s:v", "Viejo", "Button") });
            g.Observar("uia://x.exe/a", new[] { new Nucleo.Elemento("s:1", "Uno", "Button") });
            return g;
        }

        // AL MIRAR OTRA VEZ, APARECE: se pulsa en el acto.
        var g1 = Mundo();
        var (b1, _, t1) = BatchCon(g1, "uia://x.exe/a", RutasDeTres);
        int miradas = 0;
        pMira.SetValue(b1, (Func<string, bool>)(aqui =>
        {
            miradas++;
            g1.Observar(aqui, new[] { new Nucleo.Elemento("s:1", "Uno", "Button"), new Nucleo.Elemento("s:v", "Viejo", "Button") });
            return true;
        }));
        var crono = System.Diagnostics.Stopwatch.StartNew();
        var r1 = b1.Recorre(new[] { new RecorrerSegunElNucleo.Paso("Viejo") });
        crono.Stop();
        Debe(t1.Count == 1 && t1[0] == "Viejo" && r1.Hechos == 1,
            $"lo que la pantalla enseña al mirar otra vez se pulsa (se pulsaron {t1.Count}: {string.Join(",", t1)}; dijo «{r1.Cuenta}»)");
        Debe(miradas >= 1, "y se miró otra vez de verdad, no se adivinó");
        // Lo que tarda es el reloj de DESPUÉS del clic (esperar a que cambie la pantalla, que aquí no cambia):
        // UN presupuesto. Si la compuerta hubiera agotado el suyo antes de mirar, serían dos.
        Debe(crono.ElapsedMilliseconds < b1.EsperaMaximaMs + 200,
            $"y en el acto: la compuerta no agota su presupuesto antes de mirar ({crono.ElapsedMilliseconds} ms; el presupuesto es {b1.EsperaMaximaMs})");

        // Y SI NI MIRANDO APARECE, sigue sin pulsarse y se dice: la 56 en pie.
        var g2 = Mundo();
        var (b2, _, t2) = BatchCon(g2, "uia://x.exe/a", RutasDeTres);
        int m2 = 0;
        pMira.SetValue(b2, (Func<string, bool>)(_ => { m2++; return false; }));
        var r2 = b2.Recorre(new[] { new RecorrerSegunElNucleo.Paso("Viejo") });
        Debe(t2.Count == 0 && r2.Hechos == 0 && m2 >= 1 && (r2.Cuenta.Contains("no lo veo") || r2.Cuenta.Contains("ahora no")),
            $"lo que no aparece ni mirando no se pulsa, y se dice (miró {m2} vez/veces; dijo «{r2.Cuenta}»)");

        // Y MIRAR NO ES UN BUCLE. Medido el 2026-09-17 sobre Wikipedia recién cargada: cada mirada costaba
        // 0,8-2,2 s, más que el freno de 600 ms, así que la compuerta miró 76 veces en 90 s sin rendirse
        // nunca —el «continue» saltaba el reloj del presupuesto—. Una mirada que cuesta más que el
        // presupuesto entero no puede repetirse: como mucho dos, al empezar y antes de rendirse.
        var g3 = Mundo();
        var (b3, _, t3) = BatchCon(g3, "uia://x.exe/a", RutasDeTres);
        int m3 = 0;
        pMira.SetValue(b3, (Func<string, bool>)(_ =>
        {
            m3++;
            if (m3 > 4) return false;                       // red de seguridad: que el juez no se cuelgue
            Thread.Sleep(b3.EsperaMaximaMs + 400);           // una mirada lenta: más que el presupuesto
            return true;                                     // «vi algo» — pero la puerta sigue sin estar
        }));
        var crono3 = System.Diagnostics.Stopwatch.StartNew();
        var r3 = b3.Recorre(new[] { new RecorrerSegunElNucleo.Paso("Viejo") });
        crono3.Stop();
        Debe(t3.Count == 0 && r3.Hechos == 0 && m3 <= 2,
            $"una mirada lenta no se repite sin fin: como mucho dos miradas, al empezar y antes de rendirse (miró {m3}; pulsó {t3.Count}; dijo «{r3.Cuenta}»)");
        Debe(crono3.ElapsedMilliseconds < b3.EsperaMaximaMs * 3 + 1200,
            $"y se rinde dentro del presupuesto más esas dos miradas ({crono3.ElapsedMilliseconds} ms)");
    }

