        Debe(!System.Text.RegularExpressions.Regex.IsMatch(c, @"^\s*RastroDelCursor\.Arrancar\(\);", System.Text.RegularExpressions.RegexOptions.Multiline),
            "el rastro del cursor sigue arrancando con la cara");
    }

    private static void LeerYUbicarseTienenPlazo()
    {
        // MEDIDO EL 2026-09-27: el Explorador tardó 252.579 ms en contestar UNA lectura del lector viejo, que no tiene
        // plazo (System.Windows.Automation no lo admite). U entero se quedó esperando: abrir la Calculadora «tardó» 350 s.
        var t = typeof(PulsarSegunElNucleo).Assembly.GetType("U.WindowsClient.Uia.Plazo");
        var con = t?.GetMethods().FirstOrDefault(m => m.Name == "Con" && m.IsGenericMethodDefinition)?.MakeGenericMethod(typeof(int));
        if (con == null) { Pendiente("Uia.Plazo.Con (leer con plazo)", "490", "054"); return; }
        object?[] a = { (Func<int>)(() => { Thread.Sleep(2000); return 7; }), 200, null };
        var crono = System.Diagnostics.Stopwatch.StartNew();
        bool aTiempo = (bool)con.Invoke(null, a)!;
        Debe(!aTiempo && crono.ElapsedMilliseconds < 450, $"una app que no contesta en 200 ms se esperó {crono.ElapsedMilliseconds} ms (a tiempo={aTiempo})");
        object?[] b = { (Func<int>)(() => 7), 200, null };
        Debe((bool)con.Invoke(null, b)! && (int)b[2]! == 7, "lo que contesta a tiempo no llegó con su valor");
        object?[] c = { (Func<int>)(() => throw new InvalidOperationException("sin proveedor")), 200, null };
        bool lanzo = false;
        try { con.Invoke(null, c); } catch (TargetInvocationException e) when (e.InnerException is InvalidOperationException) { lanzo = true; }
        Debe(lanzo, "un fallo dentro del plazo se tragó en vez de subir con su causa (aprendizaje nº3)");

        string repo = Environment.GetEnvironmentVariable("U_REPO") ?? "";
        string lector = Path.Combine(repo, "windows-client", "src", "Uia", "UiaReader.cs");
        string donde = Path.Combine(repo, "windows-client", "src", "Uia", "SurfaceLocator.cs");
        if (!File.Exists(lector) || !File.Exists(donde)) { _fallos++; Console.WriteLine("   ⚠ NO PUDE JUZGAR la parte de las fuentes: sin U_REPO."); return; }
        Debe(File.ReadAllText(lector).Contains("Plazo.Con("), "UiaReader.Read sigue leyendo sin plazo");
        Debe(File.ReadAllText(donde).Contains("Plazo.Con("), "SurfaceLocator sigue ubicándose sin plazo");
    }

    private static void DesplazarNoDuermeFijo()
    {
        // LÍNEA BASE: Desplazamiento.Mover dormía 350 ms fijos tras cada ScrollVertical (2026-09-27), también cuando el
        // porcentaje ya había cambiado al volver la llamada, que es lo normal.
        var t = typeof(SurfaceMapTools).Assembly.GetType("U.WindowsClient.Uia.Desplazamiento");
        var espera = t?.GetMethod("EsperarQueSeMueva", BindingFlags.Public | BindingFlags.Static);
        if (espera == null) { Pendiente("Desplazamiento.EsperarQueSeMueva", "484", "053"); return; }

        var crono = System.Diagnostics.Stopwatch.StartNew();
        double ya = (double)espera.Invoke(null, new object[] { (Func<double>)(() => 40.0), 10.0, 350 })!;
        Debe(ya == 40.0 && crono.ElapsedMilliseconds < 60, $"el porcentaje ya había cambiado y esperó {crono.ElapsedMilliseconds} ms (devolvió {ya})");

        crono.Restart();
        double tarde = (double)espera.Invoke(null, new object[] { (Func<double>)(() => crono.ElapsedMilliseconds >= 120 ? 55.0 : 10.0), 10.0, 350 })!;
        Debe(tarde == 55.0 && crono.ElapsedMilliseconds < 250, $"se movió a los 120 ms y se supo a los {crono.ElapsedMilliseconds} (devolvió {tarde})");

        crono.Restart();
        double quieto = (double)espera.Invoke(null, new object[] { (Func<double>)(() => 100.0), 100.0, 350 })!;
        Debe(quieto == 100.0 && crono.ElapsedMilliseconds >= 330, $"sin moverse dijo a los {crono.ElapsedMilliseconds} ms: tiene que agotar el techo antes de decir «no se movió»");
    }

    private static void LanzarUnProtocoloEsperaALaVentanaDeDelante()
    {
        var t = typeof(U.WindowsClient.SystemApi.WindowsSystemApi);
        var techo = t.GetMethod("TechoDeEspera", BindingFlags.Public | BindingFlags.Static);
        var espera = t.GetMethod("EsperarLlegada", BindingFlags.Public | BindingFlags.Static);
        if (techo == null || espera == null) { Pendiente("WindowsSystemApi.TechoDeEspera / EsperarLlegada", "482", "053"); return; }

        Debe((int)techo.Invoke(null, new object[] { "ms-settings:" })! <= 3000, "un protocolo sigue esperando más de 3 s");
        Debe((int)techo.Invoke(null, new object[] { "mailto:alguien@ejemplo.com" })! <= 3000, "mailto: sigue esperando más de 3 s");
        Debe((int)techo.Invoke(null, new object[] { "chrome" })! >= 6000, "un programa en frío necesita su paciencia: Chrome pasa de 6 s");

        // Otra ventana delante a los 150 ms: llegó, y se sabe a los 150 ms, no a los 3 s.
        var crono = System.Diagnostics.Stopwatch.StartNew();
        Func<(IntPtr, string)> cambia = () => crono.ElapsedMilliseconds < 150 ? ((IntPtr)1, "Explorador") : ((IntPtr)2, "Configuración");
        bool llego = (bool)espera.Invoke(null, new object[] { cambia, 3000 })!;
        Debe(llego && crono.ElapsedMilliseconds < 600, $"la ventana de delante cambió a los 150 ms y la espera dijo {llego} a los {crono.ElapsedMilliseconds} ms");

        // La MISMA ventana con otro título también es llegar (Apps.Llego, promesa 469).
        crono.Restart();
        Func<(IntPtr, string)> titulo = () => ((IntPtr)1, crono.ElapsedMilliseconds < 100 ? "Configuración" : "Configuración > Pantalla");
        Debe((bool)espera.Invoke(null, new object[] { titulo, 3000 })!, "el título cambió y no se contó como llegada");

        // Nada cambia: no llegó, y se dice al techo que se le dio.
        crono.Restart();
        Func<(IntPtr, string)> quieto = () => ((IntPtr)1, "Explorador");
        bool nada = (bool)espera.Invoke(null, new object[] { quieto, 400 })!;
        Debe(!nada && crono.ElapsedMilliseconds < 800, $"sin cambio dijo {nada} a los {crono.ElapsedMilliseconds} ms con techo de 400");
    }

    private static void PulsarDeSapEsperaComoSiempre()
    {
        // En SAP, UIA no ve más que un panel opaco: su huella no cambia nunca, y cortar la espera a 150 ms haría dar por
        // no-agarrado un clic mientras SAP procesa el round-trip.
        if (typeof(PulsarSegunElNucleo).GetProperty("LoQueSeVe") == null) { Pendiente("PulsarSegunElNucleo.LoQueSeVe (la espera mira lo que se ve)", "476", "053"); return; }
        const string A = "sap://NWP1", B = "sap://NV2000";
        var g = new Nucleo.Grafo();
        g.Observar(A, new[] { new Nucleo.Elemento("sap:wnd[0]/tbar[1]/btn[8]", "Ejecutar", "GuiButton") });
        var (p, _) = PulsadorConVista(g, ms => ms >= 700 ? B : A, _ => "panel opaco");
        var r = p.Pulsa("sap:wnd[0]/tbar[1]/btn[8]", "Ejecutar");
        Debe(r.Hasta == B && r.CambioLaPantalla, $"un pulso de SAP que llega a los 700 ms se perdió: hasta «{r.Hasta}» («{r.Cuenta}»)");

        // Sin lector de lo que se ve, lo de siempre: la ubicación, hasta el techo.
        var (p2, _) = PulsadorConVista(new Nucleo.Grafo(), ms => ms >= 700 ? "uia://x/b" : "uia://x/a", null);
        var r2 = p2.Pulsa("uia:name=Ir;ct=Button", "Ir");
        Debe(r2.Hasta == "uia://x/b", $"sin lector, un cambio de ubicación a los 700 ms se perdió: hasta «{r2.Hasta}»");
    }

    private static void UnCampoDeTextoNoNavega()
    {
        // MEDIDO EL 2026-09-18 en el log de tres pruebas del dueño: 50 pulsaciones, 16 sin cambio de pantalla, y de
        // esas 7 eran campos de texto (4 ComboBox, 3 Edit). Los campos cambiaron de pantalla 0 VECES DE 7. Cada una
        // costó 3,3-3,9 s: 1,8 s esperando un cambio que un campo no produce, más la consulta al terreno.
        var pCampo = typeof(PulsarSegunElNucleo).GetProperty("EsperaDeCampoMs");
        if (pCampo == null) { Pendiente("PulsarSegunElNucleo.EsperaDeCampoMs (un campo no navega)", "334", "043"); return; }

        const string A = "web://google.com", B = "web://google.com/search";
        const int Presupuesto = 1200;
        Nucleo.Grafo Mundo()
        {
            var g = new Nucleo.Grafo();
            g.Observar(A, new[]
            {
                new Nucleo.Elemento("uia:name=Search;ct=ComboBox", "Search", "ComboBox"),
                new Nucleo.Elemento("uia:name=Rename;ct=Edit", "Rename", "Edit"),
                new Nucleo.Elemento("uia:name=Guardar;ct=Button", "Guardar", "Button"),
            });
            return g;
        }
        (PulsarSegunElNucleo.Resultado R, long Ms, int Toques) Pulsa(Nucleo.Grafo g, string selector, string etiqueta, string? alTocarSeVa = null)
        {
            string donde = A; int toques = 0;
            var pulsar = new PulsarSegunElNucleo(g, () => donde, (sel, et) => { toques++; if (alTocarSeVa != null) donde = alTocarSeVa; return true; })
            { EsperaMaximaMs = Presupuesto };
            pCampo.SetValue(pulsar, 150);
            var crono = System.Diagnostics.Stopwatch.StartNew();
            var r = pulsar.Pulsa(selector, etiqueta);
            return (r, crono.ElapsedMilliseconds, toques);
        }

        // 1. UN CAMPO: se toca una vez, no se espera el presupuesto, y se dice lo que es.
        foreach (var (sel, et) in new[] { ("uia:name=Search;ct=ComboBox", "Search"), ("uia:name=Rename;ct=Edit", "Rename") })
        {
            var (r, ms, toques) = Pulsa(Mundo(), sel, et);
            Debe(r.SePudo && !r.CambioLaPantalla && toques == 1, $"«{et}» se toca UNA vez y no se cuenta como navegación (toques={toques}; «{r.Cuenta}»)");
            Debe(ms < Presupuesto / 2, $"y no se espera el presupuesto de un cambio de pantalla que un campo no produce: «{et}» tardó {ms} ms de {Presupuesto}");
            Debe(r.Cuenta.Contains("campo") && r.Cuenta.Contains("foco"), $"la respuesta dice que es un campo y que tiene el foco, para que lo siguiente sea escribir: «{r.Cuenta}»");
        }

        // 2. EL TIPO LO DICE EL SELECTOR SI EL TERRENO AÚN NO CONOCE EL ELEMENTO (la primera vez que se ve una pantalla).
        var (r2, ms2, _) = Pulsa(new Nucleo.Grafo(), "uia:aid=ti6dpd;ct=ComboBox", "Buscar");
        Debe(r2.SePudo && ms2 < Presupuesto / 2, $"un campo que el terreno todavía no conoce se reconoce por su selector ({ms2} ms; «{r2.Cuenta}»)");

        // 3. SI AUN ASÍ LA PANTALLA CAMBIÓ, manda lo que pasó: es una navegación como cualquier otra.
        var (r3, _, _) = Pulsa(Mundo(), "uia:name=Search;ct=ComboBox", "Search", alTocarSeVa: B);
        Debe(r3.SePudo && r3.CambioLaPantalla && r3.Hasta == B, $"un campo que sí navega se cuenta como navegación (quedó en «{r3.Hasta}»; «{r3.Cuenta}»)");

        // 4. LO QUE NO ES UN CAMPO ESPERA COMO SIEMPRE: un «Guardar» puede tardar en cambiar la pantalla.
        var (r4, ms4, _) = Pulsa(Mundo(), "uia:name=Guardar;ct=Button", "Guardar");
        Debe(r4.SePudo && ms4 >= Presupuesto - 100, $"un botón sigue esperando el presupuesto entero: {ms4} ms de {Presupuesto}");
        Debe(!r4.Cuenta.Contains("campo"), $"y no se le llama campo a lo que no lo es: «{r4.Cuenta}»");
    }

    // ── Spec 046: fotos de estudios de cardiología → resumen y preguntas ─────────────────────────
    //
    // Todo se pide por NOMBRE (flujo-sdd.md): el contrato tiene que compilar contra un núcleo que aún
    // no tiene U.WindowsClient.Cardio, y ahí cada promesa dice PENDIENTE, que cuenta como incumplida.
    // El modelo es de mentira y ANOTA lo que recibe: sin red, sin clave y sin pantalla.

    private static Type? Cardio(string nombre) => Capacidad("U.WindowsClient.Cardio." + nombre);

    private static MethodInfo? MetodoCardio(Type? t, string nombre, int aridad) =>
        t?.GetMethods().FirstOrDefault(m => m.Name == nombre && m.GetParameters().Length == aridad);

    /// <summary>Una respuesta con la forma de la Responses API: el texto va en output[].content[].text.</summary>
    private static string RespuestaDeOpenAI(string texto) =>
        JsonSerializer.Serialize(new
        {
            output = new object[]
            {
                new { type = "reasoning", summary = Array.Empty<object>() },
                new { type = "message", content = new object[] { new { type = "output_text", text = texto } } },
            },
        });

    /// <summary>Cuántas imágenes lleva un cuerpo de petición, y los ids que anuncian sus etiquetas.</summary>
    private static (int Imagenes, List<string> Ids) LoQueLleva(string cuerpo)
    {
        int imagenes = 0;
        var ids = new List<string>();
        using var doc = JsonDocument.Parse(cuerpo);
        if (!doc.RootElement.TryGetProperty("input", out var entrada)) return (0, ids);
        foreach (var mensaje in entrada.EnumerateArray())
        {
            if (!mensaje.TryGetProperty("content", out var contenido) || contenido.ValueKind != JsonValueKind.Array) continue;
            foreach (var parte in contenido.EnumerateArray())
            {
                string tipo = parte.TryGetProperty("type", out var ti) ? ti.GetString() ?? "" : "";
                if (tipo == "input_image") imagenes++;
                if (tipo == "input_text")
                {
                    var m = System.Text.RegularExpressions.Regex.Match(parte.GetProperty("text").GetString() ?? "", @"^Imagen \d+ — id: (\S+)$");
                    if (m.Success) ids.Add(m.Groups[1].Value);
                }
            }
        }
        return (imagenes, ids);
    }

    /// <summary>
    /// Una sesión con <paramref name="n"/> fotos f1..fn. La foto «f2» es una selfie: el modelo de
    /// mentira la marca no cardiológica y AUN ASÍ le devuelve contenido, que es lo que la 351 juzga.
    /// </summary>
    private static dynamic? SesionConFotos(int n, DateTime primera)
    {
        var tSesion = Cardio("SesionCardio");
        var tFoto = Cardio("FotoCardio");
        if (tSesion == null || tFoto == null) return null;
        dynamic s = Activator.CreateInstance(tSesion)!;
        for (int i = 1; i <= n; i++)
        {
            dynamic f = Activator.CreateInstance(tFoto)!;
            f.Id = "f" + i;
            f.Nombre = $"foto{i}.jpg";
            f.Jpeg = new byte[] { 0xFF, 0xD8, (byte)i, 0xFF, 0xD9 };
            s.Agregar(f, primera.AddMinutes(i));
        }
        return s;
    }

    /// <summary>El modelo de mentira. Anota cada cuerpo; <paramref name="fallaEn"/> hace fallar esa llamada (1-based).</summary>
    private static Func<string, CancellationToken, Task<string>> ModeloDeMentira(List<string> cuerpos, Func<int, bool>? fallaEn = null)
    {
        return (cuerpo, _) =>
        {
            cuerpos.Add(cuerpo);
            if (fallaEn != null && fallaEn(cuerpos.Count)) throw new HttpRequestException("503 Service Unavailable (de mentira)");
            var (imagenes, ids) = LoQueLleva(cuerpo);
            if (imagenes == 0)
                return Task.FromResult(RespuestaDeOpenAI("## Estudios revisados\n- ECG de 12 derivaciones (2026-09-10)\n\n## Hallazgos clave\n- **Ritmo sinusal**"));
            var resultados = ids.Select(id => id == "f2"
                ? (object)new { id, cardiologia = false, motivo_omision = "foto personal", tipo = "Selfie en Cartagena", hallazgos = new[] { "Juan Pérez sonriendo" }, valores = new[] { new { nombre = "edad", valor = "45", unidad = "años" } }, alertas = new[] { "PLAYA" } }
                : new { id, cardiologia = true, tipo = "ECG de 12 derivaciones", fecha = "2026-09-10", hallazgos = new[] { "Ritmo sinusal" }, valores = new[] { new { nombre = "FC", valor = "72", unidad = "lpm" } }, alertas = Array.Empty<string>(), confianza = "alta" });
            return Task.FromResult(RespuestaDeOpenAI("```json\n" + JsonSerializer.Serialize(new { resultados }) + "\n```"));
        };
    }

    private static void UnResultadoPorFoto()
    {
        var t = Cardio("LecturaCardio");
        var emparejar = MetodoCardio(t, "Emparejar", 2);
        if (emparejar == null) { Pendiente("Cardio.LecturaCardio.Emparejar(respuesta, ids)", "350", "046"); return; }
        List<dynamic> Emparejar(string respuesta, params string[] ids) =>
            ((System.Collections.IEnumerable)emparejar.Invoke(null, new object[] { respuesta, ids })!).Cast<dynamic>().ToList();

        // 1. ENVUELTO EN ``` Y CON TEXTO ALREDEDOR, fuera de orden y con una foto de la que no volvió nada.
        var r = Emparejar("Aquí tienes:\n```json\n{\"resultados\":[{\"id\":\"c\",\"cardiologia\":true,\"tipo\":\"ECG\"},"
                          + "{\"id\":\"a\",\"cardiologia\":false,\"motivo_omision\":\"selfie\"}]}\n```\nListo.", "a", "b", "c");
        Debe((bool)(r.Count == 3), $"un resultado por foto, ni más ni menos: salieron {r.Count} de 3");
        if (r.Count != 3) return;
        Debe((bool)((string)r[0].Id == "a" && (string)r[1].Id == "b" && (string)r[2].Id == "c"),
            $"en el orden de las fotos, no en el del modelo: [{string.Join(", ", r.Select(x => (string)x.Id))}]");
        Debe((bool)(r[2].Estado.ToString() == "Cardiologia" && (string)r[2].Tipo == "ECG"), $"«c» se empareja por su id: {r[2].Estado} «{r[2].Tipo}»");
        Debe((bool)(r[0].Estado.ToString() == "Omitida"), $"«a» es la omitida: {r[0].Estado}");
        Debe((bool)(r[1].Estado.ToString() == "SinLeer"),
            $"de «b» no volvió nada, y eso es «sin leer» —ni cardiológica ni omitida—: {r[1].Estado}");

        // 2. SI LOS IDS NO CASAN, POR ORDEN. El modelo a veces devuelve «imagen 1» en vez del id.
        var p = Emparejar("{\"resultados\":[{\"id\":\"imagen 1\",\"cardiologia\":true,\"tipo\":\"Eco\"},{\"id\":\"imagen 2\",\"cardiologia\":false}]}", "x", "y");
        Debe((bool)(p.Count == 2 && p[0].Estado.ToString() == "Cardiologia" && (string)p[0].Tipo == "Eco" && p[1].Estado.ToString() == "Omitida"),
            $"con ids que no casan se empareja por orden: [{string.Join(", ", p.Select(x => $"{x.Id}={x.Estado}"))}]");

        // 3. BASURA NO TUMBA NADA: todas quedan sin leer y se pueden reintentar.
        var b = Emparejar("Lo siento, no puedo ayudar con eso.", "m", "n");
        Debe((bool)(b.Count == 2 && b.All(x => x.Estado.ToString() == "SinLeer")),
            $"una respuesta sin JSON deja las fotos sin leer, sin excepción: [{string.Join(", ", b.Select(x => (string)x.Estado.ToString()))}]");
    }

